-- Bengali training posters for lessons 8.8–8.10 (bn) — clean 1.10-style Net Metering / Environment / Field cards
-- Lesson 8.8
UPDATE training_chapters
SET
  content = '{"level_id":"8.8","badge_name":"জরুরী রেগুলেশন (WBERC ফোকাস)","level_title":"নেট মিটারিং (Net Metering) রেগুলেশন: সৌরশক্তির নিয়ম","mission_briefing":"দিন পাল্টাচ্ছে। এখন গ্রাহক শুধু বিদ্যুৎ কেনে না, বিক্রিও করে! বাড়ির ছাদে সোলার প্যানেল বসিয়ে অতিরিক্ত বিদ্যুৎ গ্রিডে ফেরত পাঠানো—একেই বলে ''নেট মিটারিং''। কিন্তু সাবধান! এখানে লাইনম্যানের জন্য লুকিয়ে আছে এক অদৃশ্য বিপদ। আপনি ভাবছেন লাইন বন্ধ, অথচ গ্রাহকের ছাদ থেকে সোলার প্যানেল ভোল্টেজ পাঠিয়ে লাইন সজীব করে রেখেছে। এই নতুন প্রযুক্তি এবং এর সুরক্ষার নিয়ম না জানলে বড় দুর্ঘটনা ঘটতে পারে।","sections":[{"title":"১. নেট মিটারিং কী ও কীভাবে কাজ করে?","image_name":"/images/loader/net88_bidir.webp","points":[{"item_name":"বাই-ডিরেকশনাল মিটার (Bi-directional Meter)","specifications":"এটি দুই দিকেই মাপে: ''Import'' (গ্রিড থেকে নেওয়া) এবং ''Export'' (গ্রিডে দেওয়া)।","importance":"সাধারণ মিটারে সোলার লাগালে, আপনি বিদ্যুৎ দিলেও সেটা খরচ হিসেবে দেখাবে এবং বিল বেড়ে যাবে! তাই বিশেষ নেট-মিটার লাগানো বাধ্যতামূলক।","daily_check":"মিটারে দেখুন তীরের চিহ্ন (Arrow) কোন দিকে, বা ডিসপ্লেতে Import/Export আলাদা দেখাচ্ছে কি না।","image_name":"/images/loader/net88_bidir.webp","image_caption":"বাই-ডিরেকশনাল মিটার"},{"item_name":"প্রসিউমার (Prosumer)","specifications":"Producer + Consumer = Prosumer।","importance":"এরা সাধারণ গ্রাহক নয়, এরা ছোটখাটো পাওয়ার প্ল্যান্ট।","image_name":"/images/loader/net88_bidir.webp","image_caption":"প্রসিউমার = উৎপাদক + গ্রাহক"}],"image_caption":"Import · Export · প্রসিউমার"},{"title":"২. অ্যান্টি-আইলন্ডিং (Anti-islanding): জীবন রক্ষাকারী ফিচার","image_name":"/images/loader/net88_anti.webp","points":[{"item_name":"ইনভার্টারের সেফটি মেকানিজম","specifications":"গ্রিডের কারেন্ট চলে গেলে (Power Cut), সোলার ইনভার্টারটি অটোমেটিক বন্ধ হয়ে যেতে হবে।","importance":"যদি গ্রিড বন্ধ থাকার পরেও সোলার চলতে থাকে (Islanding), তবে লাইনে কাজ করতে ওঠা লাইনম্যান ''ব্যাক-ফিড'' (Back-feed) কারেন্টে মারা যাবে।","daily_check":"সোলার কানেকশন আছে এমন বাড়িতে লাইন অফ করে দেখুন ইনভার্টারও অফ হয়েছে কি না।","image_name":"/images/loader/net88_anti.webp","image_caption":"গ্রিড অফ = ইনভার্টার অফ"}],"image_caption":"অ্যান্টি-আইলন্ডিং · ব্যাক-ফিড"},{"title":"৩. ইনস্টলেশন লিমিট: কতটা বসানো যায়?","image_name":"/images/loader/net88_limit.webp","points":[{"item_name":"স্যাংশনড লোড (Sanctioned Load)","specifications":"WBERC-এর নিয়ম অনুযায়ী, গ্রাহকের অনুমোদিত লোডের ১০০% (বা নির্দিষ্ট শতাংশ)-এর বেশি সোলার বসানো যায় না।","importance":"ট্রান্সফরমারের ওপর চাপ নিয়ন্ত্রণ করতে এবং টেকনিক্যাল লস কমাতে এই নিয়ম।","image_name":"/images/loader/net88_limit.webp","image_caption":"ইনস্টলেশন লিমিট · WBERC"}],"image_caption":"স্যাংশনড লোড · ≤ ১০০%"}],"pro_tip":{"title":"ওস্তাদের মার (Pro Tips)","content":["১. ডবল চেকিং: শাটডাউন নেওয়ার সময় যদি দেখেন এলাকায় সোলার প্যানেল আছে, তবে শুধু ট্রান্সফরমার অফ করবেন না। পোল থেকে ওই বাড়ির ফিউজও খুলে দিন। বিশ্বাসে মিলায় বস্তু, কিন্তু সোলারে মিলায় মৃত্যু!","২. সবুজ স্টিকার: নেট মিটার বা সোলার কানেকশন থাকলে মিটার বক্সে বা পোলে একটা সবুজ স্টিকার বা সাবধানবাণী লাগিয়ে রাখা উচিত।","৩. বিলিং অ্যাডজাস্টমেন্ট: গ্রাহক যদি বলে \"আমি সোলার লাগিয়েছি তাও বিল আসছে\", তবে দেখুন সে ''নেট'' ইউনিটের বিল পাচ্ছে কি না। অনেক সময় জেনারেশন কম হলে বিল আসতেই পারে।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","myths":[{"myth":"সোলার বসালে লোড শেডিং-এও আমার বাড়িতে ফ্যান চলবে।","reality":"অন-গ্রিড (On-Grid) সিস্টেমে এটা হয় না। গ্রিড বন্ধ হলে সোলারও বন্ধ হয়ে যায় সেফটির (Anti-islanding) কারণে। লোড শেডিং-এ চালাতে হলে হাইব্রিড ইনভার্টার ও ব্যাটারি লাগে।"},{"myth":"সোলার লাগালে বিল শূন্য হয়ে যাবে।","reality":"পুরোপুরি ঠিক নয়। আপনি যতটা বিদ্যুৎ ব্যবহার করছেন আর যতটা তৈরি করছেন—তার পার্থক্যের বিল হবে। তাছাড়া ''ফিক্সড চার্জ'' তো দিতেই হবে।"}],"image_name":"/images/loader/net88_myth.webp","image_caption":"মিথ বনাম বাস্তবতা · নেট মিটারিং"},"advanced_section":{"title":"ব্যাংকিং অফ এনার্জি (Banking of Energy)","facts":[{"title":"বিদ্যুৎ জমানো","content":"শীতকালে যখন এসি চলে না কিন্তু ভালো রোদ থাকে, তখন গ্রাহক অতিরিক্ত বিদ্যুৎ গ্রিডে জমা (Bank) রাখতে পারে। গরমকালে যখন বেশি দরকার হবে, তখন সেই জমানো ইউনিট সে ব্যবহার করতে পারে। WBERC এই নিয়ম ঠিক করে দেয়।"},{"title":"গ্রস মিটারিং (Gross Metering)","content":"নেট মিটারিং ছাড়াও গ্রস মিটারিং আছে, যেখানে পুরো সোলার বিদ্যুৎটাই গ্রিডে বিক্রি করে দেওয়া হয় এবং নিজের খরচে আলাদা মিটার থাকে। তবে বাড়ির জন্য নেট মিটারিং-ই বেশি জনপ্রিয়।"}]}}'::jsonb,
  version = COALESCE(version, 0) + 1
WHERE id = '8.8' AND language = 'bn';

-- Lesson 8.9
UPDATE training_chapters
SET
  content = '{"level_id":"8.9","badge_name":"জরুরী রেগুলেশন (WBERC ফোকাস)","level_title":"পরিবেশগত নিয়মাবলী: রাজ্যের দৃষ্টিকোণ","mission_briefing":"বিদ্যুৎ এবং প্রকৃতি—দুজনের সম্পর্ক অনেকটা সাপে-নেউলে। গাছপালা আমাদের অক্সিজেন দেয়, কিন্তু সেই গাছের ডালই আবার আমাদের লাইনে ঠেকে ফল্ট তৈরি করে। আবার ট্রান্সফরমারের পোড়া তেল যদি মাটিতে পড়ে, তবে তা পরিবেশের বারোটা বাজিয়ে দেয়। একজন আধুনিক লাইনম্যান হিসেবে আপনার দায়িত্ব শুধু বাতি জ্বালানো নয়, পরিবেশকে বাঁচিয়ে কাজ করা। গাছ কাটার নিয়ম বা পোড়া তেল ফেলার সঠিক পদ্ধতি না জানলে ফরেস্ট ডিপার্টমেন্ট বা পলিউশন কন্ট্রোল বোর্ডের নোটিশ আপনার দরজায় কড়া নাড়তে পারে।","sections":[{"title":"১. গাছ কাটা ও ট্রি-ট্রিমিং (Right of Way)","image_name":"/images/loader/env89_tree.webp","points":[{"item_name":"কাটা বনাম ছাঁটা (Cutting vs Trimming)","specifications":"নিয়ম অনুযায়ী, আমরা শুধু গাছের ডাল ''ছাঁটতে'' পারি যা লাইনের বিপদ ঘটাচ্ছে। পুরো গাছ ''কাটা''র অধিকার আমাদের নেই।","importance":"পুরো গাছ কাটতে হলে ফরেস্ট ডিপার্টমেন্ট বা স্থানীয় পঞ্চায়েত/মিউনিসিপালিটির লিখিত অনুমতি লাগে। অনুমতি ছাড়া গাছ কাটলে আইনি মামলা (Non-bailable offense) হতে পারে।","daily_check":"শাটডাউন নিয়ে ডাল কাটার সময় খেয়াল রাখবেন যেন গাছের ক্ষতি কম হয় এবং পাখির বাসা নষ্ট না হয়।","image_name":"/images/loader/env89_tree.webp","image_caption":"ছাঁটা অনুমোদিত · কাটায় অনুমতি"},{"item_name":"রাইট অফ ওয়ে (RoW) মেইনটেন্যান্স","specifications":"লাইনের নিচে বা আশেপাশে নির্দিষ্ট দূরত্ব পর্যন্ত জায়গা পরিষ্কার রাখা।","importance":"ঝড়ের সময় ডাল পড়ে তার ছেঁড়া বা আগুন লাগার ঘটনা এড়াতে বর্ষার আগেই এই কাজ (Pre-monsoon Maintenance) সারা জরুরি।","image_name":"/images/loader/env89_tree.webp","image_caption":"RoW · প্রি-মনসুন"}],"image_caption":"ডাল ছাঁটা · পুরো গাছ কাটা নিষেধ"},{"title":"২. বর্জ্য ব্যবস্থাপনা: তেল ও ব্যাটারি","image_name":"/images/loader/env89_waste.webp","points":[{"item_name":"ট্রান্সফরমার অয়েল (Hazardous Waste)","specifications":"পোড়া তেল বা লিকেজ হওয়া তেল ড্রেনে বা মাঠে ফেলা আইনত দণ্ডনীয়।","importance":"এই তেল মাটি ও জলকে বিষাক্ত করে। এটি ড্রামে ভরে সিল করে নির্দিষ্ট ডিসপোজাল সেন্টারে পাঠাতে হয়।","daily_check":"ট্রান্সফরমার পরিবর্তনের সময় মাটিতে প্লাস্টিক শিট বিছিয়ে নিন, যাতে এক ফোঁটা তেলও মাটিতে না পড়ে।","image_name":"/images/loader/env89_waste.webp","image_caption":"পোড়া তেল ড্রেনে ফেলা নিষেধ"},{"item_name":"পুরনো ব্যাটারি (Lead Acid Battery)","specifications":"সাবস্টেশনের বাতিল ব্যাটারি শুধুমাত্র অথরাইজড রিসাইক্লারদের কাছেই বিক্রি বা ফেরত দেওয়া যায়।","importance":"ব্যাটারির সীসা (Lead) এবং এসিড পরিবেশের জন্য মারাত্মক ক্ষতিকর।","image_name":"/images/loader/env89_waste.webp","image_caption":"ব্যাটারি · অথরাইজড রিসাইকলার"}],"image_caption":"তেল · ব্যাটারি ডিসপোজাল"}],"pro_tip":{"title":"ওস্তাদের মার (Pro Tips)","content":["১. ব্যালেন্স করে চলুন: গ্রাহকের প্রিয় আম গাছ বা নারকেল গাছ কাটার আগে তাকে বুঝিয়ে বলুন—\"দাদা, গাছের ডাল তারে ঠেকলে শুধু কারেন্ট যাবে না, গাছে আগুনও লাগতে পারে।\" ঝগড়া নয়, সচেতনতাই সমাধান।","২. তেলের ড্রাম লিক?: যদি দেখেন স্টোরে রাখা তেলের ড্রাম লিক করছে, তবে সঙ্গে সঙ্গে বালু বা কাঠের গুঁড়ো (Sawdust) ছড়িয়ে দিন। জল দিয়ে ধুবেন না, তাতে তেল আরও ছড়িয়ে পড়ে।","৩. তারের টুকরো: কাজ শেষে অ্যালুমিনিয়াম বা কপার তারের ছোট টুকরো মাঠে ফেলে আসবেন না। গরু-ছাগল এগুলো খেয়ে মারা যেতে পারে।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","myths":[{"myth":"পোড়া মবিল বা ট্রান্সফরমার অয়েল আগাছা মারার জন্য খুব ভালো, তাই ওটা মাটিতে ঢেলে দিই।","reality":"এটি একটি ভয়ঙ্কর অভ্যাস! এতে মাটি চিরতরে অনুর্বর হয়ে যায় এবং ভূগর্ভস্থ জল দূষিত হয়। পরিবেশ আইন অনুযায়ী এটি বড় অপরাধ।"},{"myth":"সরকারি লাইনের ওপর গাছ থাকলে সেটা কাটার জন্য কারোর পারমিশন লাগে না।","reality":"ভুল। গাছটি যদি ফরেস্ট এরিয়া বা ব্যক্তিগত মালিকানাধীন হয়, তবে নোটিশ দেওয়া বা অনুমতি নেওয়া বাধ্যতামূলক।"}],"image_name":"/images/loader/env89_myth.webp","image_caption":"মিথ বনাম বাস্তবতা · পরিবেশ"},"advanced_section":{"title":"PCBs: নীরব ঘাতক","facts":[{"title":"Polychlorinated Biphenyls (PCBs)","content":"পুরনো দিনের ট্রান্সফরমার তেলে PCBs নামের এক ধরনের রাসায়নিক থাকত যা ক্যান্সার সৃষ্টি করতে পারে। যদিও এখন এর ব্যবহার নিষিদ্ধ, তবুও পুরনো ট্রান্সফরমার হ্যান্ডেল করার সময় গ্লাভস ও মাস্ক পরা বাধ্যতামূলক।"},{"title":"গ্রিন করিডোর","content":"নতুন হাই-টেনশন লাইন বসানোর সময় এখন ''গ্রিন করিডোর'' বা পরিবেশ-বান্ধব নকশা করা হয় যাতে বন্যপ্রাণীদের (যেমন হাতির করিডোর) চলাচলে অসুবিধা না হয়।"}]}}'::jsonb,
  version = COALESCE(version, 0) + 1
WHERE id = '8.9' AND language = 'bn';

-- Lesson 8.10
UPDATE training_chapters
SET
  content = '{"level_id":"8.10","badge_name":"জরুরী রেগুলেশন (WBERC ফোকাস)","level_title":"রেগুলেশন এবং আপনি: ফিল্ডে প্রয়োগ","mission_briefing":"অভিনন্দন! আপনি এখন রাজ্যের বিদ্যুৎ আইনের অলিগলি চিনে ফেলেছেন। কিন্তু শুধু আইন জানলেই হবে না, তাকে মাঠে প্রয়োগ করতে হবে। একজন সাধারণ মিস্ত্রি আর একজন ''সার্টিফায়েড টেকনিশিয়ান''-এর মধ্যে পার্থক্য হলো এই জ্ঞান। এই শেষ অধ্যায়ে আমরা শিখব কীভাবে এই সমস্ত নিয়মাবলীকে আপনার রক্ষাকবচ হিসেবে ব্যবহার করবেন। মনে রাখবেন, আইন আপনাকে ভয় দেখানোর জন্য নয়, আপনাকে এবং আপনার চাকরিকে বাঁচানোর জন্য।","sections":[{"title":"১. ডকুমেন্টেশন: আপনার আইনি বর্ম","image_name":"/images/loader/field810_docs.webp","points":[{"item_name":"লগবুক মেইনটেন্যান্স","specifications":"কখন শাটডাউন নিলেন, কখন ছাড়লেন, কী কাজ করলেন—সব পুঙ্খানুপুঙ্খভাবে লিখে রাখা।","importance":"কোনো দুর্ঘটনা ঘটলে তদন্ত কমিটি সবার আগে আপনার লগবুক দেখবে। সেখানে লেখা না থাকলে, ধরে নেওয়া হবে আপনি কাজটা করেননি বা নিয়ম মানেননি।","daily_check":"ডিউটি শেষে লগবুক সাইন করার আগে দুবার পড়ে দেখুন সব ঠিক আছে কি না।","image_name":"/images/loader/field810_docs.webp","image_caption":"লগবুক · লেখা নেই = প্রমাণ নেই"},{"item_name":"পারমিট বই","specifications":"PTW (Permit To Work) বইয়ের কার্বন কপি যত্ন করে রাখা।","importance":"এটি প্রমাণ করে যে আপনি আইন মেনেই লাইনে হাত দিয়েছিলেন।","image_name":"/images/loader/field810_docs.webp","image_caption":"PTW বই · আইনি প্রমাণ"}],"image_caption":"লগবুক · PTW কার্বন কপি"},{"title":"২. ব্যবহার ও আচরণ (Behavioral Code)","image_name":"/images/loader/field810_behavior.webp","points":[{"item_name":"SoP এবং গ্রাহক সেবা","specifications":"WBERC-এর SoP শুধুমাত্র টাইমিং নিয়ে নয়, গ্রাহকের সাথে ব্যবহারের কথাও বলে।","importance":"ইউনিফর্ম পরা অবস্থায় আপনি কোম্পানির প্রতিনিধি। গ্রাহকের সাথে দুর্ব্যবহার করলে কোম্পানির লাইসেন্সের শর্ত লঙ্ঘিত হয়।","daily_check":"কাজের চাপে মাথা গরম হলেও মুখে হাসি বা শান্ত ভাব বজায় রাখুন।","image_name":"/images/loader/field810_behavior.webp","image_caption":"ইউনিফর্ম = কোম্পানির প্রতিনিধি"},{"item_name":"নৈতিকতা (Ethics)","specifications":"অবৈধ কাজে সাহায্য না করা।","importance":"টাকার বিনিময়ে হুকিং করতে সাহায্য করা বা মিটার বাইপাস করে দেওয়া—এগুলো শুধু দুর্নীতি নয়, নিজের পায়ে কুড়ুল মারা। ধরা পড়লে আইন আপনাকে ছাড়বে না।","image_name":"/images/loader/field810_behavior.webp","image_caption":"হুকিং সাহায্য = নিষিদ্ধ"}],"image_caption":"SoP · ব্যবহার · নৈতিকতা"}],"pro_tip":{"title":"ওস্তাদের শেষ কথা (Final Words)","content":["১. মুখের কথায় কাজ নয়: অফিসার বা যেই হোন, ফোনে ''লাইন অফ আছে, উঠে পড়'' বললেই বিশ্বাস করবেন না। লিখিত পারমিট বা নিজের হাতে আর্থিং না করা পর্যন্ত পোল-এ উঠবেন না।","২. আইন জানুন, ভয় পাবেন না: গ্রাহক বা পুলিশ—কেউ আপনাকে ভয় দেখাতে পারবে না যদি আপনি জানেন যে আপনি ''সাপ্লাই কোড'' এবং ''সেফটি কোড'' মেনেই কাজ করছেন। জ্ঞানই আপনার শক্তি।","৩. আপডেট থাকুন: নিয়ম বদলায়। অফিসের নোটিশ বোর্ড, ট্রেনিং বা ইউনিয়ন মিটিং থেকে নতুন সার্কুলার বা নিয়মের খোঁজ রাখুন।"]},"myth_buster":{"title":"মিথ বাস্টার (Myth Buster)","myths":[{"myth":"আইন-কানুন সব বইয়ের পাতায়, মাঠে ''জুগাড়'' (Jugaad) দিয়েই কাজ চলে।","reality":"জুগাড় দিয়ে হয়তো আজ কাজ চলে যাবে, কিন্তু যেদিন দুর্ঘটনা ঘটবে, সেদিন এই জুগাড়ই আপনাকে জেলে পাঠাবে। স্ট্যান্ডার্ড পদ্ধতিই দীর্ঘমেয়াদে নিরাপদ।"},{"myth":"আমি নিচু পদের কর্মী, আমার ঘাড়ে কোনো দায় নেই, সব দায় অফিসারের।","reality":"ভুল। ইলেকট্রিসিটি অ্যাক্ট অনুযায়ী, যে ব্যক্তি প্রত্যক্ষভাবে কাজটি করছে (আপনি), সুরক্ষার প্রাথমিক দায়িত্ব তার। আপনি ''না'' বলতে পারেন যদি কাজটা নিরাপদ না মনে হয়।"}],"image_name":"/images/loader/field810_myth.webp","image_caption":"মিথ বনাম বাস্তবতা · ফিল্ড প্রয়োগ"},"advanced_section":{"title":"ক্যারিয়ার গ্রোথ ও লাইসেন্স","facts":[{"title":"সুপারভাইজরি লাইসেন্স","content":"আপনি যদি এই নিয়মকানুনগুলো ভালো করে জানেন এবং পরীক্ষায় পাশ করেন, তবে আপনি ''লাইসেন্সড সুপারভাইজার'' হতে পারেন। তখন আপনি শুধু কাজ করবেন না, অন্যের কাজ তদারকি করবেন এবং সই করবেন।"},{"title":"আইন সচেতন কর্মী","content":"কোম্পানি সবসময় এমন লোক খোঁজে যারা টেকনিক্যাল কাজের পাশাপাশি আইনি ঝামেলা এড়াতে পারে। এই জ্ঞান আপনার প্রমোশনের রাস্তা খুলে দেবে।"}]}}'::jsonb,
  version = COALESCE(version, 0) + 1
WHERE id = '8.10' AND language = 'bn';
